from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    flat = [v for row in grid for v in row]
    background = Counter(flat).most_common(1)[0][0]

    def dominant(values):
        counts = Counter(values)
        return counts.most_common(1)[0]

    # Full grid rules are the rows and columns whose dominant color differs
    # from the interior/background color.
    hlines = []
    for r, row in enumerate(grid):
        color, count = dominant(row)
        if color != background and count > w / 2:
            hlines.append(r)
    vlines = []
    for c in range(w):
        color, count = dominant([grid[r][c] for r in range(h)])
        if color != background and count > h / 2:
            vlines.append(c)

    if len(hlines) < 2 or len(vlines) < 2:
        return [row[:] for row in grid]
    line_colors = {dominant(grid[r])[0] for r in hlines}
    line_colors.update(dominant([grid[r][c] for r in range(h)])[0] for c in vlines)

    out = []
    for r0, r1 in zip(hlines, hlines[1:]):
        row = []
        for c0, c1 in zip(vlines, vlines[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            value = corners[0] if corners.count(corners[0]) == 4 else background
            row.append(background if value in line_colors else value)
        out.append(row)

    # Blank outer cells are padding, not part of the encoded picture.
    while out and all(v == background for v in out[0]):
        out.pop(0)
    while out and all(v == background for v in out[-1]):
        out.pop()
    if out:
        while out[0] and all(row[0] == background for row in out):
            for row in out:
                row.pop(0)
        while out[0] and all(row[-1] == background for row in out):
            for row in out:
                row.pop()
    return out

